/**
 * Suppresses the compatibility click generated by the touch that reveals a
 * media overlay. The guard lasts for one pointer sequence only; a later touch
 * that begins on a visible control remains a normal control interaction.
 */
export class MediaTouchRevealGuard {
  private _cleanupTimer?: ReturnType<typeof setTimeout>;
  private _pointerId?: number;

  public begin(event: PointerEvent): void {
    this.cancel();
    this._pointerId = event.pointerId;
    document.addEventListener("click", this._suppressClick, true);
  }

  public end(event: PointerEvent): void {
    if (event.pointerId !== this._pointerId) return;
    this._clearTimer();
    // The compatibility click is dispatched after pointerup and before the
    // next task. Remove the guard immediately afterward when no click occurs.
    this._cleanupTimer = setTimeout(() => this.cancel(), 0);
  }

  public cancel(): void {
    this._clearTimer();
    this._pointerId = undefined;
    document.removeEventListener("click", this._suppressClick, true);
  }

  private _clearTimer(): void {
    if (this._cleanupTimer === undefined) return;
    clearTimeout(this._cleanupTimer);
    this._cleanupTimer = undefined;
  }

  private readonly _suppressClick = (event: MouseEvent): void => {
    event.preventDefault();
    event.stopImmediatePropagation();
    this.cancel();
  };
}
